def _tos_accepted():
    accepted = os.environ.get(_ACCEPT_ENV_VAR, "").strip().lower()
    return accepted in {"y", "yes", "1", "true"}


def _require_tos_acceptance():
    if _tos_accepted():
        return

    if not sys.stdin or not sys.stdin.isatty():
        raise SystemExit(
            "PyCrSDK TOS acceptance is required before first-time installation. "
            f"Re-run in an interactive terminal or set {_ACCEPT_ENV_VAR}=y."
        )

    print(JP_TOS)
    print(EN_TOS)
    answer = input("Do you accept the terms above? [y/N]: ").strip().lower()
    if answer != "y":
        raise SystemExit("PyCrSDK installation aborted because the TOS was not accepted.")


def _install_dlls():
    src = os.path.join(os.path.dirname(__file__), "CrAdapter")
    dst = os.path.join(os.path.dirname(sys.executable), "CrAdapter")
    if not os.path.exists(dst):
        try:
            _require_tos_acceptance()
            shutil.copytree(src, dst, dirs_exist_ok=True)
            print(f"Installed DLLs to {dst}")
        except Exception as e:
            print(f"Warning: could not install DLLs: {e}")

_install_dlls()